import re,os,collections
root='AlgebraicJacobian'
def mods():
    out=set()
    for dp,dn,fn in os.walk(root):
        for f in fn:
            if f.endswith('.lean'):
                p=os.path.join(dp,f)[:-5].replace('/','.')
                out.add(p)
    return out
all_mods=mods()
print('modules on disk (excluding root file):', len(all_mods))
imports=collections.defaultdict(set)
for m in all_mods|{'AlgebraicJacobian'}:
    p=m.replace('.','/')+'.lean'
    if not os.path.exists(p): continue
    for line in open(p):
        mm=re.match(r'^import\s+([\w.]+)',line)
        if mm: imports[m].add(mm.group(1))
seen=set()
stack=['AlgebraicJacobian']
while stack:
    x=stack.pop()
    if x in seen: continue
    seen.add(x)
    for y in imports.get(x,()):
        if y.startswith('AlgebraicJacobian'): stack.append(y)
reached=seen-{'AlgebraicJacobian'}
print('rooted:', len(reached & all_mods))
print('unrooted:', sorted(all_mods-reached))
EOF

