def reach(start):
    seen=set(); st=[start]
    while st:
        x=st.pop()
        if x in seen: continue
        seen.add(x); st.extend(imports.get(x,()))
    return seen-{start}
for s in ['AlgebraicJacobian.Jacobian','AlgebraicJacobian.Genus']:
    if os.path.exists(s.replace('.','/')+'.lean'):
        r=reach(s); print(s,'reaches',len(r),'modules (+itself =',len(r)+1,')')
